/// <summary>
/// Editor tooling for the "Snow Boarder" lab.
///
/// Everything the lab asks for that is not plain code (a main menu scene, the HUD,
/// the collectibles, the power-ups, the obstacle course, the weather and the end
/// screen) is generated by this script so the scenes stay consistent and can be
/// rebuilt at any time.
///
/// Usage
///   Menu:  Lab 2  ->  Build All Scenes
///   Batch: Unity.exe -batchmode -quit -projectPath &lt;project&gt; -executeMethod Lab2SceneBuilder.BuildAll
/// </summary>
public static class Lab2SceneBuilder
{
    const string ScenesFolder = "Assets/Scenes";
    const string SpritesFolder = "Assets/Sprites";
    const string MaterialsFolder = "Assets/Materials";

    const string MainMenuScenePath = ScenesFolder + "/MainMenu.unity";
    const string LevelScenePath = ScenesFolder + "/Level1.unity";
    const string EndScenePath = ScenesFolder + "/EndGame.unity";

    // =====================================================================
    //  Menu entries
    // =====================================================================

    [MenuItem("Lab 2/Build All Scenes then Smoke Test")]
    public static void BuildAllThenSmokeTest()
    {
        BuildAll();
        Lab2SmokeTest.Run();
    }

    [MenuItem("Lab 2/Build All Scenes then Screenshot")]
    public static void BuildAllThenScreenshot()
    {
        BuildAll();
        Lab2Screenshot.Run();
    }

    [MenuItem("Lab 2/Build All Scenes then Input Test")]
    public static void BuildAllThenInputTest()
    {
        BuildAll();
        Lab2InputTest.Run();
    }

    [MenuItem("Lab 2/Build All Scenes")]
    public static void BuildAll()
    {
        GenerateSprites();
        GenerateMaterials();

        BuildMainMenuScene();
        EnhanceLevelScene();
        BuildLevelVariants();
        BuildEndGameScene();

        ApplyBuildSettings();
        VerifyScenes();
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        // Leave the editor on the main menu so pressing Play "just works".
        EditorSceneManager.OpenScene(MainMenuScenePath, OpenSceneMode.Single);

        Debug.Log("[Lab2] All scenes built successfully.");
    }

    /// <summary>Logs how many components lost their script (should be zero).</summary>
    static void VerifyScenes()
    {
        string[] scenes =
        {
            MainMenuScenePath, Presets[0].ScenePath, Presets[1].ScenePath, Presets[2].ScenePath, EndScenePath
        };

        foreach (string path in scenes)
        {
            Scene scene = EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
            int missing = 0;

            foreach (GameObject root in scene.GetRootGameObjects())
            {
                Transform[] transforms = root.GetComponentsInChildren<Transform>(true);
                foreach (Transform transform in transforms)
                {
                    missing += GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(transform.gameObject);
                }
            }

            Debug.Log($"[Lab2] {path}: {missing} missing script(s).");
        }
    }

    [MenuItem("Lab 2/Rebuild Main Menu Scene")]
    public static void BuildMainMenuOnly()
    {
        GenerateSprites();
        GenerateMaterials();
        BuildMainMenuScene();
        ApplyBuildSettings();
        AssetDatabase.SaveAssets();
