        AssetDatabase.SaveAssets();
    }

    // =====================================================================
    //  Generated art (snowflakes / power-up icons / snow particle)
    // =====================================================================

    static void GenerateSprites()
    {
        EnsureFolder(SpritesFolder);

        WriteTextureColor("Sky_Gradient", 32, 256, (x, y) => SkyGradient(x, y, 256));
        WriteTexture("Snowflake", 64, 64, (x, y) => Snowflake(x, y, 64));
        WriteTexture("Powerup_Speed", 64, 64, (x, y) => Badge(x, y, 64, Chevron));
        WriteTexture("Powerup_Invincible", 64, 64, (x, y) => Badge(x, y, 64, Ring));
        WriteTexture("Powerup_Life", 64, 64, (x, y) => Badge(x, y, 64, Plus));
        WriteTexture("Snow_Particle", 32, 32, (x, y) => Snowflake(x, y, 32));
        WriteTexture("Ramp", 64, 64, (x, y) => RampShape(x, y, 64), SpriteAlignment.LeftCenter);
        WriteTexture("Hill_Silhouette", 256, 64, (x, y) => HillSilhouette(x, y, 256, 64));
        WriteTextureColor("Ice_Patch", 160, 64, (x, y) => IcePatch(x, y, 160, 64));
        WriteTextureColor("Sky_Dark", 32, 256, (x, y) => SkyDarkGradient(x, y, 256));
        WriteTextureColor("Button_Fill", 64, 64, (x, y) => RoundedBoxAlpha(x, y, 64, 0f),
            SpriteAlignment.Center, new Vector4(16f, 16f, 16f, 16f));
        WriteTextureColor("Button_Outline", 64, 64, (x, y) => RoundedBoxAlpha(x, y, 64, 2.5f),
            SpriteAlignment.Center, new Vector4(16f, 16f, 16f, 16f));
        WriteTexture("Puff", 64, 64, (x, y) => Puff(x, y, 64));
        WriteTextureColor("Finish_Checker", 128, 32, (x, y) => Checker(x, y, 128, 32));
        WriteTexture("Pole", 8, 64, (x, y) => 1f);
    }

    /// <summary>Black / white checkered pattern used by the finish banner.</summary>
    static Color Checker(int x, int y, int width, int height)
    {
        const int cell = 16;
        bool dark = ((x / cell) + (y / cell)) % 2 == 0;
        return dark ? new Color(0.09f, 0.10f, 0.12f, 1f) : new Color(1f, 1f, 1f, 1f);
    }

    /// <summary>Soft round blob used for the snow spray / crash particles.</summary>
    static float Puff(int x, int y, int size)
    {
        float c = (size - 1) * 0.5f;
        float dx = x - c;
        float dy = y - c;
        float d = Mathf.Sqrt(dx * dx + dy * dy) / (size * 0.5f);
        return Mathf.Pow(Mathf.Clamp01(1f - d), 1.6f);
    }

    /// <summary>Menu sky: dark navy on top fading into a muted steel blue.</summary>
    static Color SkyDarkGradient(int x, int y, int height)
    {
        float t = y / (float)(height - 1);
        Color bottom = new Color(0.30f, 0.43f, 0.55f);
        Color middle = new Color(0.13f, 0.21f, 0.29f);
        Color top = new Color(0.05f, 0.09f, 0.14f);

        return t < 0.5f
            ? Color.Lerp(bottom, middle, t * 2f)
            : Color.Lerp(middle, top, (t - 0.5f) * 2f);
    }

    /// <summary>Signed distance to a rounded box centred in a square texture.</summary>
    static float RoundedBoxSdf(int x, int y, int size, float corner)
    {
        float c = (size - 1) * 0.5f;
        float half = size * 0.5f - 2f;
        float qx = Mathf.Abs(x - c) - (half - corner);
        float qy = Mathf.Abs(y - c) - (half - corner);
        float ax = Mathf.Max(qx, 0f);
        float ay = Mathf.Max(qy, 0f);
        return Mathf.Sqrt(ax * ax + ay * ay) + Mathf.Min(Mathf.Max(qx, qy), 0f) - corner;
    }

    /// <summary>Rounded box (thickness = 0) or its outline (thickness &gt; 0), as alpha.</summary>
    static Color RoundedBoxAlpha(int x, int y, int size, float thickness)
    {
        float d = RoundedBoxSdf(x, y, size, 14f);

        bool inside = thickness <= 0f ? d <= 0f : (d <= 0f && d >= -thickness);
        return inside ? Color.white : new Color(1f, 1f, 1f, 0f);
    }

    /// <summary>Translucent icy patch - reads clearly as "this will slow you down".</summary>
    static Color IcePatch(int x, int y, int width, int height)
    {
        float cx = (width - 1) * 0.5f;
        float cy = (height - 1) * 0.5f;
        float a = width * 0.5f - 3f;
        float b = height * 0.5f - 3f;
        float dx = (x - cx) / a;
        float dy = (y - cy) / b;
        float r = Mathf.Sqrt(dx * dx + dy * dy);

        if (r > 1f)
        {
            return new Color(0f, 0f, 0f, 0f);
        }

        Color rim = new Color(1f, 1f, 1f, 0.95f);
        Color fill = new Color(0.5f, 0.8f, 0.98f, 0.8f);
        return r > 0.75f ? rim : fill;
    }

    /// <summary>Vertical winter sky gradient (deep blue at the top, pale near the snow).</summary>
    static Color SkyGradient(int x, int y, int height)
    {
        float t = y / (float)(height - 1);
        Color bottom = new Color(0.88f, 0.94f, 0.99f);
        Color middle = new Color(0.53f, 0.78f, 0.94f);
        Color top = new Color(0.19f, 0.40f, 0.70f);

        return t < 0.5f
            ? Color.Lerp(bottom, middle, t * 2f)
            : Color.Lerp(middle, top, (t - 0.5f) * 2f);
    }

    /// <summary>Soft mountain silhouette used as a distant parallax layer.</summary>
    static float HillSilhouette(int x, int y, int width, int height)
    {
        float u = x / (float)(width - 1);
        float ridge = 0.35f
                      + 0.28f * Mathf.Sin(u * Mathf.PI * 2.0f + 1.2f)
                      + 0.16f * Mathf.Sin(u * Mathf.PI * 5.0f + 0.4f);
        float limit = Mathf.Clamp01(ridge) * height;
        return y <= limit ? 1f : 0f;
    }

    /// <summary>Right triangle rising to the right, pivot on the left edge.</summary>
    static float RampShape(int x, int y, int size)
    {
        return y <= x * 0.95f ? 1f : 0f;
    }

    static void EnsureFolder(string path)
    {
        if (!AssetDatabase.IsValidFolder(path))
        {
            string parent = Path.GetDirectoryName(path).Replace('\\', '/');
            string leaf = Path.GetFileName(path);
            if (!AssetDatabase.IsValidFolder(parent))
            {
                EnsureFolder(parent);
            }
            AssetDatabase.CreateFolder(parent, leaf);
        }
    }

    static void WriteTexture(string name, int width, int height, System.Func<int, int, float> painter,
        SpriteAlignment alignment = SpriteAlignment.Center)
    {
        WriteTextureColor(name, width, height,
            (x, y) => new Color(1f, 1f, 1f, Mathf.Clamp01(painter(x, y))), alignment);
    }

    static void WriteTextureColor(string name, int width, int height, System.Func<int, int, Color> painter,
        SpriteAlignment alignment = SpriteAlignment.Center, Vector4 border = default)
    {
        string path = $"{SpritesFolder}/{name}.png";

        Texture2D texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Color[] pixels = new Color[width * height];
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                pixels[y * width + x] = painter(x, y);
            }
        }
        texture.SetPixels(pixels);
        texture.Apply();

        string absolute = Path.Combine(Application.dataPath, path.Substring("Assets/".Length));
        Directory.CreateDirectory(Path.GetDirectoryName(absolute));
        File.WriteAllBytes(absolute, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);

        AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);

        TextureImporter importer = (TextureImporter)AssetImporter.GetAtPath(path);
        importer.textureType = TextureImporterType.Sprite;
        importer.spritePixelsPerUnit = 64f;
        importer.alphaIsTransparency = true;
        importer.mipmapEnabled = false;

        if (alignment != SpriteAlignment.Center || border != Vector4.zero)
        {
            TextureImporterSettings settings = new TextureImporterSettings();
            importer.ReadTextureSettings(settings);
            if (alignment != SpriteAlignment.Center)
            {
                settings.spriteAlignment = (int)alignment;
            }
            if (border != Vector4.zero)
            {
                settings.spriteBorder = border;
            }
            importer.SetTextureSettings(settings);
        }

        importer.SaveAndReimport();
    }

    // --- tiny procedural painters (return alpha 0..1) --------------------

    static float Snowflake(int x, int y, int size)
    {
        float cx = (size - 1) * 0.5f;
        float cy = (size - 1) * 0.5f;
        float dx = x - cx;
        float dy = y - cy;
        float radius = size * 0.45f;
        float dist = Mathf.Sqrt(dx * dx + dy * dy);
        float alpha = 0f;

        if (dist <= size * 0.09f)
        {
            alpha = 1f;
        }

        for (int i = 0; i < 6; i++)
        {
            float angle = i * Mathf.PI / 3f;
            float ax = Mathf.Cos(angle);
            float ay = Mathf.Sin(angle);
            float projection = dx * ax + dy * ay;
            float perpendicular = Mathf.Abs(-dx * ay + dy * ax);

            if (projection >= 0f && projection <= radius && perpendicular < size * 0.045f)
            {
                alpha = Mathf.Max(alpha, 1f - projection / radius * 0.25f);
            }
        }

        return alpha;
    }

    static float Badge(int x, int y, int size, System.Func<float, float, float> symbol)
    {
        float cx = (size - 1) * 0.5f;
        float cy = (size - 1) * 0.5f;
        float dx = (x - cx) / (size * 0.5f);
        float dy = (y - cy) / (size * 0.5f);
        float dist = Mathf.Sqrt(dx * dx + dy * dy);

        if (dist > 1f)
        {
            return 0f;
        }

        // The colour comes from the sprite renderer tint, so the texture only encodes
        // coverage: a soft disc, a bright ring and a bright symbol.
        float disc = dist <= 0.92f ? 0.3f : 0f;
        float ring = Mathf.Abs(dist - 0.82f) < 0.06f ? 1f : 0f;
        float sym = symbol(dx, dy);
        return Mathf.Max(disc, Mathf.Max(ring, sym));
    }

    static float Chevron(float dx, float dy)
    {
        // two ">" chevrons
        float a = Mathf.Abs(Mathf.Abs(dy) - (dx + 0.15f) * 0.7f);
        float b = Mathf.Abs(Mathf.Abs(dy) - (dx - 0.35f) * 0.7f);
        float hit = 0f;
        if (dx > -0.15f && dx < 0.15f && a < 0.09f) hit = 1f;
        if (dx > 0.35f && dx < 0.65f && b < 0.09f) hit = 1f;
        return hit;
    }

    static float Ring(float dx, float dy)
    {
        float dist = Mathf.Sqrt(dx * dx + dy * dy);
        return Mathf.Abs(dist - 0.45f) < 0.1f ? 1f : 0f;
    }

    static float Plus(float dx, float dy)
    {
        if (Mathf.Abs(dx) < 0.14f && Mathf.Abs(dy) < 0.5f) return 1f;
        if (Mathf.Abs(dy) < 0.14f && Mathf.Abs(dx) < 0.5f) return 1f;
        return 0f;
    }

    static float RoundedRect(int x, int y, int size)
    {
        float cx = (size - 1) * 0.5f;
        float cy = (size - 1) * 0.5f;
        float bx = size * 0.5f - 8f;
        float by = size * 0.5f - 8f;
        float qx = Mathf.Max(Mathf.Abs(x - cx) - bx, 0f);
        float qy = Mathf.Max(Mathf.Abs(y - cy) - by, 0f);
        return Mathf.Sqrt(qx * qx + qy * qy) <= 8f ? 1f : 0f;
    }

    static void GenerateMaterials()
    {
        EnsureFolder(MaterialsFolder);

        EnsureParticleMaterial("SnowParticle", "Snow_Particle");
        EnsureParticleMaterial("SnowPuff", "Puff");
    }

    static void EnsureParticleMaterial(string materialName, string textureName)
    {
        string path = $"{MaterialsFolder}/{materialName}.mat";
        Shader shader = FindParticleShader();
        Material material = AssetDatabase.LoadAssetAtPath<Material>(path);

        if (material == null)
        {
            material = new Material(shader);
            AssetDatabase.CreateAsset(material, path);
        }
        else
        {
            material.shader = shader;
        }

        // URP shaders use _BaseMap, built-in shaders use _MainTex - set whichever exists,
        // otherwise the particles render as plain white quads.
        Texture2D texture = AssetDatabase.LoadAssetAtPath<Texture2D>($"{SpritesFolder}/{textureName}.png");
        if (texture != null)
        {
            material.mainTexture = texture;
            if (material.HasProperty("_BaseMap")) material.SetTexture("_BaseMap", texture);
            if (material.HasProperty("_MainTex")) material.SetTexture("_MainTex", texture);
        }

        if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", Color.white);
        if (material.HasProperty("_Surface")) material.SetFloat("_Surface", 1f);
        material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
        material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

        EditorUtility.SetDirty(material);
        AssetDatabase.SaveAssets();
    }

    static Shader FindParticleShader()
    {
        string[] candidates =
        {
            "Universal Render Pipeline/Particles/Unlit",
            "Universal Render Pipeline/2D/Sprite-Unlit-Default",
            "Sprites/Default",
            "Legacy Shaders/Particles/Alpha Blended"
        };

        foreach (string name in candidates)
        {
            Shader shader = Shader.Find(name);
            if (shader != null)
            {
                return shader;
            }
        }

        return Shader.Find("Sprites/Default");
    }

