    static void BuildMainMenuScene()
    {
        Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

        CreateMenuCamera("Menu Camera", new Color(0.05f, 0.09f, 0.14f));
        Canvas canvas = CreateCanvas("Main Menu Canvas");

        Sprite sky = LoadSprite("Sky_Dark");
        Sprite hills = LoadSprite("Hill_Silhouette");
        Sprite tree = LoadSprite("Snow-Tree-2");
        Sprite flake = LoadSprite("Snowflake");

        // ---- background ---------------------------------------------------
        CreateSpriteImage(canvas.transform, "Sky", sky, Color.white,
            new Vector2(0f, 0f), new Vector2(1f, 1f), Vector2.zero, Vector2.zero);

        CreateSpriteImage(canvas.transform, "Mountain", hills, new Color(0.12f, 0.18f, 0.24f, 1f),
            new Vector2(0f, 0f), new Vector2(1f, 0.66f), Vector2.zero, Vector2.zero);

        CreateSpriteImage(canvas.transform, "SnowSlope", hills, new Color(0.88f, 0.93f, 0.98f, 1f),
            new Vector2(0f, 0f), new Vector2(1f, 0.30f), Vector2.zero, Vector2.zero);

