    static void EnhanceLevelScene()
    {
        Scene scene = EditorSceneManager.OpenScene(LevelScenePath, OpenSceneMode.Single);

        GameObject player = FindByName(scene, "Barry");
        GameObject terrain = FindByName(scene, "Level Sprite Shape");

        if (player == null || terrain == null)
        {
            Debug.LogError("[Lab2] Level1 is missing 'Barry' or 'Level Sprite Shape'. Aborting level setup.");
            return;
        }

        CleanUpGenerated(scene);

        // The snow spray / crash effects must use the soft particle material, otherwise
        // they render as hard white squares.
        AssignParticleMaterial("Dust Particles", "SnowPuff");
        AssignParticleMaterial("Crash Effect", "SnowPuff");
        AssignParticleMaterial("Finish Effect", "SnowPuff");

        // --- managers -----------------------------------------------------
        EnsureManager<GameManager>(scene, "Game Manager");
        EnsureManager<ScoreManager>(scene, "Score Manager");

        // --- player setup ---------------------------------------------------
        SetupPlayer(player);

        // --- background -----------------------------------------------------
        BuildBackground(scene);

        // --- HUD -----------------------------------------------------------
        BuildHud(scene);

        // --- camera ---------------------------------------------------------
        SetCameraDistance(scene);

        // NOTE: this scene is the master/prefab for the three difficulty variants; the
        // course content itself is generated per difficulty by BuildLevelVariants().
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene, LevelScenePath);
    }

    /// <summary>Pulls the camera back a little so more of the track is visible.</summary>
    static void SetCameraDistance(Scene scene)
    {
        const float orthographicSize = 12.5f;

        Camera camera = FindCamera(scene);
        if (camera != null)
        {
            camera.orthographicSize = orthographicSize;
        }

        // The Cinemachine virtual camera drives the real camera, so its lens must match.
        GameObject rig = FindByName(scene, "VC Follow Camera");
        if (rig == null)
        {
            return;
        }

        foreach (Component component in rig.GetComponents<Component>())
        {
            if (component == null || component.GetType().Name != "CinemachineVirtualCamera")
            {
                continue;
            }

            SerializedObject serialized = new SerializedObject(component);
            SerializedProperty lens = serialized.FindProperty("m_Lens");
            SerializedProperty size = lens != null ? lens.FindPropertyRelative("OrthographicSize") : null;
            if (size != null)
            {
                size.floatValue = orthographicSize;
                serialized.ApplyModifiedPropertiesWithoutUndo();
            }
        }
    }

    static void CleanUpGenerated(Scene scene)
    {
        string[] generated =
        {
            "Gameplay", "HUD Canvas", "HUDController", "Weather", "Sky", "Distant Hills",
            "Snow Flurry", "Finish Banner", "Finish Post L", "Finish Post R"
        };
        foreach (string name in generated)
        {
            GameObject existing = FindByName(scene, name);
            if (existing != null)
            {
                Object.DestroyImmediate(existing);
            }
        }
    }

    static void EnsureManager<T>(Scene scene, string name) where T : Component
    {
        GameObject host = FindByName(scene, name);
        if (host == null)
        {
            host = new GameObject(name);
        }

        if (host.GetComponent<T>() == null)
        {
            host.AddComponent<T>();
        }
    }

    /// <summary>
    /// Writes the intended tuning into the saved scene (NOT called: the designer's
    /// inspector values in the scene must be preserved across rebuilds).
    /// </summary>
    static void TunePlayer(GameObject player)
    {
        PlayerController controller = player.GetComponent<PlayerController>();
        if (controller == null)
        {
            return;
        }

        SetFloat(controller, "torqueAmount", 10f);
        SetFloat(controller, "maxTurnSpeed", 800f);
        SetFloat(controller, "carveTurnRate", 600f);
        SetFloat(controller, "carveAngle", 40f);
        SetFloat(controller, "rightingTurnRate", 400f);
        SetFloat(controller, "carveAcceleration", 9000f);
        SetFloat(controller, "spinAcceleration", 9000f);
        SetFloat(controller, "boostSpeed", 40f);
        SetFloat(controller, "baseSpeed", 20f);
        SetFloat(controller, "brakeSpeed", 8f);
        SetFloat(controller, "boostDuration", 2.5f);
        SetFloat(controller, "jumpForce", 18f);
        SetFloat(controller, "jumpCooldown", 0.12f);
        SetFloat(controller, "jumpBufferTime", 0.18f);
        SetFloat(controller, "coyoteTime", 0.15f);
        SetFloat(controller, "fallMargin", 22f);
    }

    /// <summary>
    /// Prepares "Barry": trick tracking, the invincibility blink and - most importantly -
    /// a wide, thick "snowboard" collider. The original scene used a very thin capsule
    /// which could slip through the tessellated slope collider at high speed.
    /// </summary>
    static void SetupPlayer(GameObject player)
    {
        if (player.GetComponent<TrickController>() == null)
        {
            player.AddComponent<TrickController>();
        }

        if (player.GetComponent<InvincibilityBlink>() == null)
        {
            player.AddComponent<InvincibilityBlink>();
        }

        CapsuleCollider2D capsule = player.GetComponent<CapsuleCollider2D>();
        if (capsule != null)
        {
            capsule.direction = CapsuleDirection2D.Horizontal;
            capsule.offset = new Vector2(0f, -0.99f);
            capsule.size = new Vector2(3f, 0.6f);
        }

        Rigidbody2D body = player.GetComponent<Rigidbody2D>();
        if (body != null)
        {
            body.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
            body.interpolation = RigidbodyInterpolation2D.Interpolate;
            body.sleepMode = RigidbodySleepMode2D.NeverSleep;

            // Lower angular drag so the carve / spin controller is predictable.
            body.angularDamping = 6f;
        }

        // NOTE: the tuning values (turn rates, jump force, speeds...) are intentionally
        // left exactly as they are in the scene, so the designer's inspector values are
        // never overwritten by a rebuild.
    }

    /// <summary>
    /// Moves the finish gate to the end of the (now much longer) course and makes its
    /// trigger tall enough to cover the snow surface at that height.
    /// </summary>
    static void MoveFinishLine(Scene scene, List<Vector2> surface, float finishX)
    {
        GameObject finish = FindByName(scene, "Finish Line");
        if (finish == null)
        {
            return;
        }

        float y = SurfaceY(surface, finishX);
        if (float.IsNegativeInfinity(y))
        {
            y = finish.transform.position.y;
        }

        // The original gate sits ~4 units above the snow - keep that relationship.
        finish.transform.position = new Vector3(finishX, y + 3.9f, 0f);

        BoxCollider2D box = finish.GetComponent<BoxCollider2D>();
        if (box != null)
        {
            box.isTrigger = true;
            box.size = new Vector2(2f, 26f);
            box.offset = new Vector2(0f, 6.5f);
        }

        // Hide the gate art that ships with the level and draw a black / white checkered
        // finish banner instead, so the end of the course is unmistakable.
        foreach (string name in new[] { "Post", "Top" })
        {
            GameObject part = FindByName(scene, name);
            SpriteRenderer renderer = part != null ? part.GetComponent<SpriteRenderer>() : null;
            if (renderer != null)
            {
                renderer.enabled = false;
            }
        }

        BuildFinishFlag(finish.transform);
    }

    static void BuildFinishFlag(Transform parent)
    {
        Material spriteMaterial = FindSpriteMaterial();
        Sprite checker = LoadSprite("Finish_Checker");
        Sprite pole = LoadSprite("Pole");

        for (int side = -1; side <= 1; side += 2)
        {
            GameObject post = new GameObject(side < 0 ? "Finish Post L" : "Finish Post R");
            post.transform.SetParent(parent);
            post.transform.localPosition = new Vector3(side * 3.2f, -0.9f, 0f);
            post.transform.localScale = new Vector3(1f, 6f, 1f);

            SpriteRenderer renderer = post.AddComponent<SpriteRenderer>();
            renderer.sprite = pole;
            renderer.color = new Color(0.93f, 0.95f, 1f, 1f);
            renderer.sortingOrder = 6;
            if (spriteMaterial != null)
            {
                renderer.sharedMaterial = spriteMaterial;
            }
        }

        GameObject banner = new GameObject("Finish Banner");
        banner.transform.SetParent(parent);
        banner.transform.localPosition = new Vector3(0f, 3f, 0f);
        banner.transform.localScale = new Vector3(3.5f, 3.2f, 1f);

        SpriteRenderer bannerRenderer = banner.AddComponent<SpriteRenderer>();
        bannerRenderer.sprite = checker;
        bannerRenderer.sortingOrder = 7;
        if (spriteMaterial != null)
        {
            bannerRenderer.sharedMaterial = spriteMaterial;
        }
    }

    /// <summary>
    /// Rescales a scene particle effect with absolute values, because the crash burst that
    /// ships with the level is big enough to cover the whole screen.
    /// </summary>
    static void ConfigureEffect(GameObject host, float minSize, float maxSize, float rate)
    {
        if (host == null)
        {
            return;
        }

        ParticleSystem particles = host.GetComponent<ParticleSystem>();
        if (particles == null)
        {
            return;
        }

        ParticleSystem.MainModule main = particles.main;
        main.startSize = new ParticleSystem.MinMaxCurve(minSize, maxSize);
        main.startSpeedMultiplier = 0.7f;

        if (rate > 0f)
        {
            ParticleSystem.EmissionModule emission = particles.emission;
            emission.rateOverTime = rate;
        }
    }

    /// <summary>
    /// Replaces the Sprite Shape fill texture (a flat blue plate) with the snow tile and a
    /// soft icy tint, so the mountain looks like a snow slope.
    /// </summary>
    static void SnowifyTerrain(GameObject terrain)
    {
        SpriteShapeRenderer shapeRenderer = terrain.GetComponent<SpriteShapeRenderer>();
        if (shapeRenderer == null)
        {
            return;
        }

        Texture2D snowTile = AssetDatabase.LoadAssetAtPath<Texture2D>($"{SpritesFolder}/Snow-tile-low-res.png");
        if (snowTile != null)
        {
            SerializedObject serialized = new SerializedObject(shapeRenderer);
            SerializedProperty texture = serialized.FindProperty("m_ShapeTexture");
            if (texture != null)
            {
                texture.objectReferenceValue = snowTile;
                serialized.ApplyModifiedPropertiesWithoutUndo();
            }
        }

        shapeRenderer.color = new Color(0.93f, 0.97f, 1f, 1f);
    }

    /// <summary>
    /// Reshapes the supplied mountain: stretched horizontally and squashed vertically, so
    /// the course is much longer and reads as gentle rolling hills. The top of the mountain
    /// is kept where it was so the scenery that ships with the level still lines up.
    /// </summary>
    static void ReshapeTerrain(GameObject terrain, float targetScaleX, float targetScaleY)
    {
        Transform transform = terrain.transform;
        float originalY = transform.localScale.y;

        float peakLocalY = 21f;
        EdgeCollider2D edge = terrain.GetComponent<EdgeCollider2D>();
        if (edge != null)
        {
            float highest = float.NegativeInfinity;
            foreach (Vector2 point in edge.points)
            {
                highest = Mathf.Max(highest, point.y);
            }

            if (highest > 0f)
            {
                peakLocalY = highest;
            }
        }

        transform.localScale = new Vector3(targetScaleX, targetScaleY, transform.localScale.z);
        transform.position += Vector3.up * ((originalY - targetScaleY) * peakLocalY);
    }

    // ---------------------------------------------------------------------
    //  The three difficulty variants
    // ---------------------------------------------------------------------

    /// <summary>Layout of one difficulty: how long / how steep / how busy the course is.</summary>
    class LevelPreset
    {
        public string Name;
        public float ScaleX;
        public float ScaleY;
        /// <summary>Where the finish sits, as a fraction of the mountain width.</summary>
        public float FinishFraction;
        public float CollectibleSpacing;
        public int Obstacles;
        public int Trees;
        public int Ramps;
        public int PowerUps;
        /// <summary>Clear distance after the start (no obstacles there).</summary>
        public float StartGap;

        public string ScenePath => $"{ScenesFolder}/Level1_{Name}.unity";
    }

    static readonly LevelPreset[] Presets =
    {
        // Easy: short-ish, flat, almost no obstacles, no big cliff.
        new LevelPreset
        {
            Name = "Easy", ScaleX = 2.15f, ScaleY = 0.5f, FinishFraction = 0.66f,
            CollectibleSpacing = 13f, Obstacles = 4, Trees = 1, Ramps = 4, PowerUps = 5,
            StartGap = 120f
        },
        // Normal: the "standard" snowy course - a few obstacles, a couple of hills.
        new LevelPreset
        {
            Name = "Normal", ScaleX = 2.3f, ScaleY = 0.85f, FinishFraction = 0.9f,
            CollectibleSpacing = 11f, Obstacles = 8, Trees = 2, Ramps = 6, PowerUps = 6,
            StartGap = 110f
        },
        // Hard: long, steep, busy - the big drop is part of the course.
        new LevelPreset
        {
            Name = "Hard", ScaleX = 2.3f, ScaleY = 1.15f, FinishFraction = 0.95f,
            CollectibleSpacing = 10f, Obstacles = 15, Trees = 5, Ramps = 8, PowerUps = 7,
            StartGap = 90f
        },
    };

    [MenuItem("Lab 2/Rebuild Level Variants")]
    public static void BuildLevelVariantsOnly()
    {
        GenerateSprites();
        GenerateMaterials();
        BuildLevelVariants();
        ApplyBuildSettings();
        AssetDatabase.SaveAssets();
    }

    /// <summary>Builds Level1_Easy / Level1_Normal / Level1_Hard from the master level scene.</summary>
    static void BuildLevelVariants()
    {
        foreach (LevelPreset preset in Presets)
        {
            Scene scene = EditorSceneManager.OpenScene(LevelScenePath, OpenSceneMode.Single);

            GameObject player = FindByName(scene, "Barry");
            GameObject terrain = FindByName(scene, "Level Sprite Shape");

            if (player == null || terrain == null)
            {
                Debug.LogError("[Lab2] The master level is missing 'Barry' or 'Level Sprite Shape'.");
                return;
            }

            ApplyPreset(scene, player, terrain, preset);

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, preset.ScenePath);
            Debug.Log($"[Lab2] Built {preset.ScenePath}");
        }
    }

    /// <summary>Removes only the course content (the HUD / sky stay in the master).</summary>
    static void CleanUpCourseContent(Scene scene)
    {
        string[] generated = { "Gameplay", "Weather", "Finish Banner", "Finish Post L", "Finish Post R" };

        foreach (string name in generated)
        {
            GameObject existing = FindByName(scene, name);
            if (existing != null)
            {
                Object.DestroyImmediate(existing);
            }
        }
    }

    static void ApplyPreset(Scene scene, GameObject player, GameObject terrain, LevelPreset preset)
    {
        CleanUpCourseContent(scene);

        ReshapeTerrain(terrain, preset.ScaleX, preset.ScaleY);

        List<Vector2> surface = BuildSurface(terrain);
        if (surface.Count == 0)
        {
            Debug.LogError("[Lab2] Could not read the slope surface.");
            return;
        }

        float leftX = float.MaxValue;
        float rightX = float.MinValue;
        foreach (Vector2 point in surface)
        {
            leftX = Mathf.Min(leftX, point.x);
            rightX = Mathf.Max(rightX, point.x);
        }

        float width = rightX - leftX;
        float spawnX = leftX + 24f;
        float finishX = leftX + width * preset.FinishFraction;

        RealignScenery(surface);
        PlacePlayerAtStart(player, surface, spawnX);
        MoveFinishLine(scene, surface, finishX);

        // ---- content ----------------------------------------------------
        GameObject gameplay = new GameObject("Gameplay");

        float from = spawnX + preset.StartGap;
        float to = finishX - 30f;

        PlaceCollectibles(gameplay.transform, surface, spawnX + 30f, to, preset.CollectibleSpacing);
        PlacePowerUps(gameplay.transform, surface, Spread(from, to, preset.PowerUps));
        PlaceObstacles(gameplay.transform, surface, BuildObstacleLayout(preset, from, to));
        PlaceRamps(gameplay.transform, surface, Spread(from - 25f, to, preset.Ramps));

        ConfigureEffect(FindByName(scene, "Crash Effect"), 0.3f, 0.8f, 40f);
        ConfigureEffect(FindByName(scene, "Finish Effect"), 0.35f, 0.9f, 40f);
        ConfigureEffect(FindByName(scene, "Dust Particles"), 0.15f, 0.4f, -1f);

        BuildWeather(scene);
    }

    /// <summary>Evenly spread <paramref name="count"/> positions between from and to.</summary>
    static float[] Spread(float from, float to, int count)
    {
        if (count <= 0)
        {
            return new float[0];
        }

        float[] result = new float[count];
        if (count == 1)
        {
            result[0] = (from + to) * 0.5f;
            return result;
        }

        for (int i = 0; i < count; i++)
        {
            result[i] = Mathf.Lerp(from, to, i / (float)(count - 1));
        }

        return result;
    }

    /// <summary>Trees and ice patches spread along the course, trees first on the list.</summary>
    static (float x, bool isTree)[] BuildObstacleLayout(LevelPreset preset, float from, float to)
    {
        var layout = new System.Collections.Generic.List<(float x, bool isTree)>();

        if (preset.Obstacles <= 0)
        {
            return layout.ToArray();
        }

        for (int i = 0; i < preset.Obstacles; i++)
        {
            float t = preset.Obstacles == 1 ? 0.5f : i / (float)(preset.Obstacles - 1);
            float x = Mathf.Lerp(from, to, t);

            // Trees are grouped at the front of the list so they are evenly spread too.
            bool isTree = i % Mathf.Max(1, preset.Obstacles / Mathf.Max(1, preset.Trees)) == 0
                          && CountTrees(layout) < preset.Trees;

            layout.Add((x, isTree));
        }

        return layout.ToArray();
    }

    static int CountTrees(System.Collections.Generic.List<(float x, bool isTree)> layout)
    {
        int count = 0;
        foreach (var item in layout)
        {
            if (item.isTree)
            {
                count++;
            }
        }

        return count;
    }

    /// <summary>Puts the background trees / rocks back on the reshaped slope.</summary>
    static void RealignScenery(List<Vector2> surface)
    {
        Transform[] all = Object.FindObjectsByType<Transform>(FindObjectsInactive.Include);

        foreach (Transform candidate in all)
        {
            if (candidate == null || candidate.GetComponent<Obstacle>() != null)
            {
                continue;
            }

            bool decor = candidate.name.StartsWith("Snow-Tree") || candidate.name.StartsWith("Snow-Rock");
            if (!decor)
            {
                continue;
            }

            float y = SurfaceY(surface, candidate.position.x);
            if (float.IsNegativeInfinity(y))
            {
                continue;
            }

            SpriteRenderer renderer = candidate.GetComponent<SpriteRenderer>();
            float halfHeight = renderer != null ? Mathf.Abs(renderer.bounds.extents.y) : 3f;

            // Bottom on the snow, and drawn behind the terrain / the player.
            candidate.position = new Vector3(
                candidate.position.x, y + halfHeight * 0.92f, candidate.position.z);

            if (renderer != null)
            {
                renderer.sortingOrder = -5;
            }
        }
    }

    /// <summary>Moves the boarder (and the camera rig) to the top of the reshaped slope.</summary>
    static void PlacePlayerAtStart(GameObject player, List<Vector2> surface, float spawnX)
    {
        float y = SurfaceY(surface, spawnX);
        if (float.IsNegativeInfinity(y))
        {
            return;
        }

        player.transform.position = new Vector3(spawnX, y + 2.5f, player.transform.position.z);

        foreach (string name in new[] { "Main Camera", "VC Follow Camera" })
        {
            GameObject camera = GameObject.Find(name);
            if (camera != null)
            {
                camera.transform.position =
                    new Vector3(spawnX, y + 6f, camera.transform.position.z);
            }
        }
    }

    /// <summary>Points a scene particle system at one of the generated particle materials.</summary>
    static void AssignParticleMaterial(string objectName, string materialName)
    {
        GameObject host = GameObject.Find(objectName);
        if (host == null)
        {
            return;
        }

        ParticleSystemRenderer renderer = host.GetComponent<ParticleSystemRenderer>();
        Material material = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialsFolder}/{materialName}.mat");
        if (renderer != null && material != null)
        {
            renderer.sharedMaterial = material;
        }
    }

    /// <summary>Winter sky + distant hills that travel with the camera.</summary>
    static void BuildBackground(Scene scene)
    {
        Camera camera = FindCamera(scene);
        if (camera == null)
        {
            return;
        }

        camera.backgroundColor = new Color(0.62f, 0.82f, 0.94f);

        Sprite sky = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/Sky_Gradient.png");
        Sprite hills = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/Hill_Silhouette.png");
        Material spriteMaterial = FindSpriteMaterial();

        GameObject skyGo = new GameObject("Sky");
        skyGo.transform.SetParent(camera.transform, false);
        skyGo.transform.localPosition = new Vector3(0f, 0f, 12f);
        skyGo.transform.localScale = new Vector3(90f, 7f, 1f);
        SpriteRenderer skyRenderer = skyGo.AddComponent<SpriteRenderer>();
        skyRenderer.sprite = sky;
        skyRenderer.sortingOrder = -1000;
        if (spriteMaterial != null)
        {
            skyRenderer.sharedMaterial = spriteMaterial;
        }

        GameObject hillsGo = new GameObject("Distant Hills");
        hillsGo.transform.SetParent(camera.transform, false);
        hillsGo.transform.localPosition = new Vector3(0f, -3.5f, 11.5f);
        hillsGo.transform.localScale = new Vector3(24f, 14f, 1f);
        SpriteRenderer hillsRenderer = hillsGo.AddComponent<SpriteRenderer>();
        hillsRenderer.sprite = hills;
        hillsRenderer.color = new Color(0.87f, 0.93f, 0.99f, 1f);
        hillsRenderer.sortingOrder = -999;
        if (spriteMaterial != null)
        {
            hillsRenderer.sharedMaterial = spriteMaterial;
        }

        // Give the clouds a gentle parallax so the scenery feels deeper.
        Transform cameraTransform = camera.transform;
        Transform[] all = Object.FindObjectsByType<Transform>(FindObjectsInactive.Include);
        foreach (Transform candidate in all)
        {
            if (candidate == null || !candidate.name.StartsWith("Sprite_Cloud"))
            {
                continue;
            }

            Parallax parallax = candidate.GetComponent<Parallax>();
            if (parallax == null)
            {
                parallax = candidate.gameObject.AddComponent<Parallax>();
            }

            SetReference(parallax, "targetCamera", cameraTransform);
            SetFloat(parallax, "depth", 0.95f);
        }
    }

    /// <summary>Reconstructs the world-space top surface of the level from its collider.</summary>
    static List<Vector2> BuildSurface(GameObject terrain)
    {
        EdgeCollider2D edge = terrain.GetComponent<EdgeCollider2D>();
        List<Vector2> worldPoints = new List<Vector2>();

        if (edge == null)
        {
            Debug.LogWarning("[Lab2] 'Level Sprite Shape' has no EdgeCollider2D - using the renderer bounds.");
            return worldPoints;
        }

        Vector2[] local = edge.points;
        foreach (Vector2 point in local)
        {
            worldPoints.Add(edge.transform.TransformPoint(point));
        }

        return worldPoints;
    }

    /// <summary>Highest surface Y at the given world X (or float.NaN when off the slope).</summary>
    static float SurfaceY(List<Vector2> points, float x)
    {
        float best = float.NegativeInfinity;

        for (int i = 0; i < points.Count - 1; i++)
        {
            Vector2 a = points[i];
            Vector2 b = points[i + 1];

            if ((a.x <= x && x <= b.x) || (b.x <= x && x <= a.x))
            {
                float t = Mathf.Approximately(a.x, b.x) ? 0f : (x - a.x) / (b.x - a.x);
                best = Mathf.Max(best, Mathf.Lerp(a.y, b.y, t));
            }
        }

        return best;
    }

    static void PlaceCollectibles(Transform parent, List<Vector2> surface, float fromX, float toX, float spacing)
    {
        Sprite snowflake = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/Snowflake.png");
        Material spriteMaterial = FindSpriteMaterial();
        Color snowflakeTint = new Color(0.86f, 0.95f, 1f, 1f);

        int index = 0;

        for (float x = fromX; x <= toX; x += spacing)
        {
            float y = SurfaceY(surface, x);
            if (float.IsNegativeInfinity(y))
            {
                continue;
            }

            // Every third group is an arc, so the player has to jump for them.
            float lift = 2.4f + (index % 3 == 1 ? 1.6f : 0f) + Mathf.Sin(x * 0.35f) * 0.6f;

            GameObject go = new GameObject($"Snowflake ({index})");
            go.transform.SetParent(parent);
            go.transform.position = new Vector3(x, y + lift, 0f);

            SpriteRenderer renderer = go.AddComponent<SpriteRenderer>();
            renderer.sprite = snowflake;
            renderer.color = snowflakeTint;
            renderer.sortingOrder = 10;
            if (spriteMaterial != null)
            {
                renderer.sharedMaterial = spriteMaterial;
            }

            CircleCollider2D collider = go.AddComponent<CircleCollider2D>();
            collider.isTrigger = true;
            collider.radius = 0.6f;

            go.AddComponent<Collectible>();

            index++;
        }
    }

    static void PlacePowerUps(Transform parent, List<Vector2> surface, float[] positions)
    {
        PowerUp.Kind[] kinds = { PowerUp.Kind.SpeedBoost, PowerUp.Kind.Invincibility, PowerUp.Kind.ExtraLife };

        Material spriteMaterial = FindSpriteMaterial();

        for (int index = 0; index < positions.Length; index++)
        {
            PowerUp.Kind kind = kinds[index % kinds.Length];
            string spriteName = kind == PowerUp.Kind.ExtraLife ? "Powerup_Life"
                : kind == PowerUp.Kind.Invincibility ? "Powerup_Invincible" : "Powerup_Speed";
            Color color = kind == PowerUp.Kind.ExtraLife ? new Color(1f, 0.36f, 0.5f)
                : kind == PowerUp.Kind.Invincibility ? new Color(0.25f, 0.75f, 1f)
                : new Color(1f, 0.62f, 0.12f);

            float x = positions[index];
            float y = SurfaceY(surface, x);
            if (float.IsNegativeInfinity(y))
            {
                continue;
            }

            Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/{spriteName}.png");

            GameObject go = new GameObject("PowerUp " + kind);
            go.transform.SetParent(parent);
            go.transform.position = new Vector3(x, y + 3.2f, 0f);

            SpriteRenderer renderer = go.AddComponent<SpriteRenderer>();
            renderer.sprite = sprite;
            renderer.color = color;
            renderer.sortingOrder = 11;
            if (spriteMaterial != null)
            {
                renderer.sharedMaterial = spriteMaterial;
            }

            CircleCollider2D collider = go.AddComponent<CircleCollider2D>();
            collider.isTrigger = true;
            collider.radius = 0.7f;

            PowerUp power = go.AddComponent<PowerUp>();
            SetEnum(power, "kind", (int)kind);
        }
    }

    static void PlaceObstacles(Transform parent, List<Vector2> surface, (float x, bool isTree)[] layout)
    {
        Sprite treeSprite = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/Snow-Tree-2.png");
        Sprite iceSprite = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/Ice_Patch.png");
        Material spriteMaterial = FindSpriteMaterial();

        int treeIndex = 0;
        int iceIndex = 0;

        foreach (var item in layout)
        {
            float y = SurfaceY(surface, item.x);
            if (float.IsNegativeInfinity(y))
            {
                continue;
            }

            Sprite sprite = item.isTree ? treeSprite : iceSprite;
            if (sprite == null)
            {
                continue;
            }

            Vector2 spriteSize = sprite.bounds.size;
            float targetHeight = item.isTree ? 3.5f : 0.9f;
            float scale = targetHeight / Mathf.Max(0.001f, spriteSize.y);

            string name = item.isTree ? $"Obstacle Tree {treeIndex++}" : $"Ice Patch {iceIndex++}";

            GameObject go = new GameObject(name);
            go.transform.SetParent(parent);

            if (item.isTree)
            {
                go.transform.localScale = Vector3.one * scale;
                go.transform.position = new Vector3(item.x, y + spriteSize.y * 0.5f * 0.9f * scale, 0f);

                SpriteRenderer renderer = go.AddComponent<SpriteRenderer>();
                renderer.sprite = sprite;
                renderer.sortingOrder = 3;
                if (spriteMaterial != null)
                {
                    renderer.sharedMaterial = spriteMaterial;
                }

                BoxCollider2D box = go.AddComponent<BoxCollider2D>();
                box.size = new Vector2(spriteSize.x * 0.32f, spriteSize.y * 0.45f);
                box.offset = new Vector2(0f, -spriteSize.y * 0.2f);
            }
            else
            {
                go.transform.localScale = new Vector3(scale * 2.4f, scale, 1f);
                go.transform.position = new Vector3(item.x, y + targetHeight * 0.25f, 0f);

                SpriteRenderer renderer = go.AddComponent<SpriteRenderer>();
                renderer.sprite = sprite;
                renderer.sortingOrder = 2;
                if (spriteMaterial != null)
                {
                    renderer.sharedMaterial = spriteMaterial;
                }

                // The collider matches the drawn patch, and being a trigger it can never
                // trap the player - it only costs speed.
                BoxCollider2D box = go.AddComponent<BoxCollider2D>();
                box.size = spriteSize;
                box.offset = Vector2.zero;
                box.isTrigger = true;
            }

            Obstacle obstacle = go.AddComponent<Obstacle>();
            SetEnum(obstacle, "kind", (int)(item.isTree ? Obstacle.Kind.Fatal : Obstacle.Kind.Slow));
        }
    }

    static void PlaceRamps(Transform parent, List<Vector2> surface, float[] rampPositions)
    {
        // The ramp sprite is a wedge whose pivot sits on its left tip, so the object can
        // be placed straight on the slope surface. It is a trigger that launches the
        // boarder - a solid wedge could trap a player that arrives too slowly.
        Sprite rampSprite = AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/Ramp.png");
        Material spriteMaterial = FindSpriteMaterial();

        int index = 0;
        foreach (float x in rampPositions)
        {
            float y = SurfaceY(surface, x);
            if (float.IsNegativeInfinity(y))
            {
                continue;
            }

            GameObject go = new GameObject($"Ramp ({index++})");
            go.transform.SetParent(parent);
            go.transform.rotation = Quaternion.identity;
            go.transform.localScale = new Vector3(3.6f, 1.2f, 1f);
            go.transform.position = new Vector3(x, y + 0.6f, 0f);

            SpriteRenderer renderer = go.AddComponent<SpriteRenderer>();
            renderer.sprite = rampSprite;
            renderer.color = new Color(0.55f, 0.85f, 1f, 1f);
            renderer.sortingOrder = 4;
            if (spriteMaterial != null)
            {
                renderer.sharedMaterial = spriteMaterial;
            }

            BoxCollider2D box = go.AddComponent<BoxCollider2D>();
            box.size = Vector2.one;
            box.offset = new Vector2(0.5f, 0f);
            box.isTrigger = true;

            go.AddComponent<Ramp>();
        }
    }

