    static void BuildWeather(Scene scene)
    {
        GameObject go = new GameObject("Weather");
        ParticleSystem snow = go.AddComponent<ParticleSystem>();

        ParticleSystem.MainModule main = snow.main;
        main.loop = true;
        main.startLifetime = new ParticleSystem.MinMaxCurve(4f, 7f);
        main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.8f);
        main.startSize = new ParticleSystem.MinMaxCurve(0.15f, 0.5f);
        main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
        main.maxParticles = 1200;
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.gravityModifier = 0.03f;

        ParticleSystem.EmissionModule emission = snow.emission;
        emission.rateOverTime = 70f;

        ParticleSystem.ShapeModule shape = snow.shape;
        shape.shapeType = ParticleSystemShapeType.Box;
        shape.scale = new Vector3(70f, 1f, 1f);
        shape.position = new Vector3(0f, 18f, 0f);

        ParticleSystemRenderer renderer = go.GetComponent<ParticleSystemRenderer>();
        renderer.renderMode = ParticleSystemRenderMode.Billboard;
        renderer.sortingOrder = 60;
        Material material = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialsFolder}/SnowParticle.mat");
        if (material != null)
        {
            renderer.sharedMaterial = material;
        }

        SnowfallController controller = go.AddComponent<SnowfallController>();
        Camera camera = FindCamera(scene);
        SetReference(controller, "targetCamera", camera);
    }

