    static Camera CreateMenuCamera(string name, Color background)
    {
        GameObject go = new GameObject(name);
        Camera camera = go.AddComponent<Camera>();
        camera.clearFlags = CameraClearFlags.SolidColor;
        camera.backgroundColor = background;
        camera.orthographic = true;
        camera.orthographicSize = 5f;
        go.AddComponent<AudioListener>();
        go.tag = "MainCamera";
        return camera;
    }

    static Canvas CreateCanvas(string name, float planeDistance = 0f)
    {
        GameObject go = new GameObject(name, typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));
        Canvas canvas = go.GetComponent<Canvas>();
        canvas.renderMode = RenderMode.ScreenSpaceOverlay;

        CanvasScaler scaler = go.GetComponent<CanvasScaler>();
        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
        scaler.referenceResolution = new Vector2(1920f, 1080f);
        scaler.matchWidthOrHeight = 0.5f;

        EnsureEventSystem();
        return canvas;
    }

    static void EnsureEventSystem()
    {
        if (Object.FindAnyObjectByType<EventSystem>() != null)
        {
            return;
        }

        new GameObject("EventSystem", typeof(EventSystem), typeof(InputSystemUIInputModule));
    }

    static GameObject CreateImage(Transform parent, string name, Color color,
        Vector2 anchorMin, Vector2 anchorMax, Vector2 anchoredPosition, Vector2 size)
    {
        GameObject go = new GameObject(name, typeof(Image));
        go.transform.SetParent(parent, false);

        Image image = go.GetComponent<Image>();
        image.color = color;

        RectTransform rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = anchoredPosition;
        rect.sizeDelta = size;
        return go;
    }

    static GameObject CreatePanel(Transform parent, string name, Vector2 size)
    {
        GameObject panel = CreateImage(parent, name, new Color(0.10f, 0.20f, 0.32f, 0.95f),
            new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, size);
        return panel;
    }

    static Image CreateSpriteImage(Transform parent, string name, Sprite sprite, Color color,
        Vector2 anchorMin, Vector2 anchorMax, Vector2 anchoredPosition, Vector2 size)
    {
        GameObject go = CreateImage(parent, name, color, anchorMin, anchorMax, anchoredPosition, size);
        Image image = go.GetComponent<Image>();
        image.sprite = sprite;
        image.type = Image.Type.Simple;
        image.raycastTarget = false;
        return image;
    }

    static Sprite LoadSprite(string name)
    {
        return AssetDatabase.LoadAssetAtPath<Sprite>($"{SpritesFolder}/{name}.png");
    }

    /// <summary>Flat, rounded, bordered button - the look used by the main menu.</summary>
    static Button CreateRoundedButton(Transform parent, string name, string label, Vector2 anchoredPosition,
        Vector2 size, Color fill, Color textColor, Vector2 anchor, int fontSize, bool primary)
    {
        GameObject go = new GameObject(name, typeof(Image), typeof(Button));
        go.transform.SetParent(parent, false);

        Image image = go.GetComponent<Image>();
        image.sprite = LoadSprite("Button_Fill");
        image.type = Image.Type.Sliced;
        image.color = fill;
        image.pixelsPerUnitMultiplier = 1f;

        RectTransform rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchor;
        rect.anchorMax = anchor;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = anchoredPosition;
        rect.sizeDelta = size;

        Button button = go.GetComponent<Button>();
        button.targetGraphic = image;

        GameObject outlineGo = new GameObject("Outline", typeof(Image));
        outlineGo.transform.SetParent(go.transform, false);
        Image outline = outlineGo.GetComponent<Image>();
        outline.sprite = LoadSprite("Button_Outline");
        outline.type = Image.Type.Sliced;
        outline.color = primary
            ? new Color(1f, 0.86f, 0.62f, 0.85f)
            : new Color(0.55f, 0.68f, 0.80f, 0.75f);
        outline.raycastTarget = false;

        RectTransform outlineRect = outlineGo.GetComponent<RectTransform>();
        outlineRect.anchorMin = Vector2.zero;
        outlineRect.anchorMax = Vector2.one;
        outlineRect.sizeDelta = Vector2.zero;
        outlineRect.anchoredPosition = Vector2.zero;

        Text text = CreateText(go.transform, "Text", label, new Vector2(0.5f, 0.5f), size * 0.9f,
            fontSize, TextAnchor.MiddleCenter, textColor);
        text.fontStyle = FontStyle.Bold;
        text.rectTransform.anchorMin = Vector2.zero;
        text.rectTransform.anchorMax = Vector2.one;
        text.rectTransform.sizeDelta = Vector2.zero;
        text.rectTransform.anchoredPosition = Vector2.zero;

        return button;
    }

    static Text CreateText(Transform parent, string name, string content,
        Vector2 anchor, Vector2 size, int fontSize, TextAnchor alignment, Color color)
    {
        return CreateText(parent, name, content, anchor, size, fontSize, alignment, color, anchor, Vector2.zero);
    }

    static Text CreateText(Transform parent, string name, string content,
        Vector2 anchor, Vector2 size, int fontSize, TextAnchor alignment, Color color,
        Vector2 anchorPivot, Vector2 anchoredPosition)
    {
        GameObject go = new GameObject(name, typeof(Text));
        go.transform.SetParent(parent, false);
        Text text = go.GetComponent<Text>();
        text.text = content;
        text.font = GetFont();
        text.fontSize = fontSize;
        text.alignment = alignment;
        text.color = color;
        text.horizontalOverflow = HorizontalWrapMode.Overflow;
        text.verticalOverflow = VerticalWrapMode.Overflow;
        text.raycastTarget = false;

        // A subtle dark outline keeps every label readable over the busy winter art.
        Outline outline = go.AddComponent<Outline>();
        outline.effectColor = new Color(0f, 0f, 0f, 0.55f);
        outline.effectDistance = new Vector2(1.5f, -1.5f);
        outline.useGraphicAlpha = true;

        RectTransform rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchorPivot;
        rect.anchorMax = anchorPivot;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = anchoredPosition;
        rect.sizeDelta = size;
        return text;
    }

    static Font GetFont()
    {
        Font font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        if (font == null)
        {
            font = Resources.GetBuiltinResource<Font>("Arial.ttf");
        }

        return font;
    }

    static Button CreateButton(Transform parent, string name, string label, Vector2 anchoredPosition,
        Vector2 size, Color color)
    {
        return CreateButton(parent, name, label, anchoredPosition, size, color, new Vector2(0.5f, 0.5f), 36);
    }

    static Button CreateButton(Transform parent, string name, string label, Vector2 anchoredPosition,
        Vector2 size, Color color, Vector2 anchor, int fontSize)
    {
        GameObject go = new GameObject(name, typeof(Image), typeof(Button));
        go.transform.SetParent(parent, false);

        Image image = go.GetComponent<Image>();
        image.color = color;

        RectTransform rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchor;
        rect.anchorMax = anchor;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = anchoredPosition;
        rect.sizeDelta = size;

        Button button = go.GetComponent<Button>();
        button.targetGraphic = image;

        Text text = CreateText(go.transform, "Text", label, new Vector2(0.5f, 0.5f), size * 0.9f,
            fontSize, TextAnchor.MiddleCenter, Color.white);
        text.rectTransform.anchorMin = Vector2.zero;
        text.rectTransform.anchorMax = Vector2.one;
        text.rectTransform.sizeDelta = Vector2.zero;
        text.rectTransform.anchoredPosition = Vector2.zero;

        return button;
    }

    static Slider CreateSlider(Transform parent, string name, Vector2 anchor, Vector2 size)
    {
        GameObject go = new GameObject(name, typeof(Slider));
        go.transform.SetParent(parent, false);

        RectTransform rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchor;
        rect.anchorMax = anchor;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = Vector2.zero;
        rect.sizeDelta = size;

        GameObject background = CreateImage(go.transform, "Background", new Color(0.2f, 0.28f, 0.38f, 1f),
            new Vector2(0f, 0.3f), new Vector2(1f, 0.7f), Vector2.zero, Vector2.zero);

        GameObject fillArea = new GameObject("Fill Area", typeof(RectTransform));
        fillArea.transform.SetParent(go.transform, false);
        RectTransform fillAreaRect = fillArea.GetComponent<RectTransform>();
        fillAreaRect.anchorMin = new Vector2(0f, 0.3f);
        fillAreaRect.anchorMax = new Vector2(1f, 0.7f);
        fillAreaRect.sizeDelta = Vector2.zero;
        fillAreaRect.anchoredPosition = Vector2.zero;

        GameObject fill = CreateImage(fillArea.transform, "Fill", new Color(0.24f, 0.62f, 0.95f, 1f),
            new Vector2(0f, 0f), new Vector2(1f, 1f), Vector2.zero, Vector2.zero);

        GameObject handleArea = new GameObject("Handle Slide Area", typeof(RectTransform));
        handleArea.transform.SetParent(go.transform, false);
        RectTransform handleAreaRect = handleArea.GetComponent<RectTransform>();
        handleAreaRect.anchorMin = Vector2.zero;
        handleAreaRect.anchorMax = Vector2.one;
        handleAreaRect.sizeDelta = Vector2.zero;
        handleAreaRect.anchoredPosition = Vector2.zero;

        GameObject handle = CreateImage(handleArea.transform, "Handle", new Color(1f, 1f, 1f, 1f),
            new Vector2(0f, 0f), new Vector2(0f, 1f), Vector2.zero, new Vector2(24f, 0f));

        Slider slider = go.GetComponent<Slider>();
        slider.fillRect = fill.GetComponent<RectTransform>();
        slider.handleRect = handle.GetComponent<RectTransform>();
        slider.targetGraphic = handle.GetComponent<Image>();
        slider.direction = Slider.Direction.LeftToRight;
        slider.minValue = 0f;
        slider.maxValue = 1f;
        slider.value = 0.8f;

        return slider;
    }

    static Material FindSpriteMaterial()
    {
        SpriteRenderer sample = Object.FindAnyObjectByType<SpriteRenderer>();
        if (sample != null && sample.sharedMaterial != null)
        {
            return sample.sharedMaterial;
        }

        return null;
    }

    static Camera FindCamera(Scene scene)
    {
        foreach (GameObject root in scene.GetRootGameObjects())
        {
            Camera camera = root.GetComponentInChildren<Camera>();
            if (camera != null)
            {
                return camera;
            }
        }

        return null;
    }

    static GameObject FindByName(Scene scene, string name)
    {
        foreach (GameObject root in scene.GetRootGameObjects())
        {
            GameObject found = FindRecursive(root, name);
            if (found != null)
            {
                return found;
            }
        }

        return null;
    }

    static GameObject FindRecursive(GameObject current, string name)
    {
        if (current.name == name)
        {
            return current;
        }

        for (int i = 0; i < current.transform.childCount; i++)
        {
            GameObject found = FindRecursive(current.transform.GetChild(i).gameObject, name);
            if (found != null)
            {
                return found;
            }
        }

        return null;
    }

    static void SetReference(Object target, string field, Object value)
    {
        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty property = serialized.FindProperty(field);
        if (property != null)
        {
            property.objectReferenceValue = value;
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }
        else
        {
            Debug.LogWarning($"[Lab2] Field '{field}' not found on {target}.");
        }
    }

    static void SetEnum(Object target, string field, int value)
    {
        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty property = serialized.FindProperty(field);
        if (property != null)
        {
            property.enumValueIndex = value;
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }
    }

    static void SetFloat(Object target, string field, float value)
    {
        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty property = serialized.FindProperty(field);
        if (property != null)
        {
            property.floatValue = value;
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }
    }

    static void ApplyBuildSettings()
    {
        List<EditorBuildSettingsScene> scenes = new List<EditorBuildSettingsScene>
        {
            new EditorBuildSettingsScene(MainMenuScenePath, true),
            new EditorBuildSettingsScene(Presets[0].ScenePath, true),
            new EditorBuildSettingsScene(Presets[1].ScenePath, true),
            new EditorBuildSettingsScene(Presets[2].ScenePath, true),
            new EditorBuildSettingsScene(EndScenePath, true)
        };

        EditorBuildSettings.scenes = scenes.ToArray();
        Debug.Log("[Lab2] Build settings updated (MainMenu -> Level1_Easy/Normal/Hard -> EndGame).");
    }
}
